import{_ as a,o as r,c as o,a5 as i}from"./chunks/framework.BwlBv862.js";const b=JSON.parse('{"title":"Registro del candidato TikTools 4.2.1-rc.2","description":"","frontmatter":{"title":"Registro del candidato TikTools 4.2.1-rc.2","docId":"releases.4.2.1-rc.2","translationKey":"releases.4.2.1-rc.2","locale":"es","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"af1ea83a9bb29fd23f3e4c086d976fb5abecaff8e20965cc6db9b5c64d5b191e","translationRevision":"3d951d9305ec3f413c43e3520b2d127b49d9b9bb8bf09a7ced6ca9c620089c27","order":20},"headers":[],"relativePath":"es/releases/4.2.1-rc.2.md","filePath":"es/releases/4.2.1-rc.2.md","lastUpdated":1794611623000}'),s={name:"es/releases/4.2.1-rc.2.md"};function c(n,e,t,l,d,p){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="tiktools-421-rc2" tabindex="-1">TikTools 4.2.1-rc.2 <a class="header-anchor" href="#tiktools-421-rc2" aria-label="Permalink to &quot;TikTools 4.2.1-rc.2 {#tiktools-421-rc2}&quot;">​</a></h1><h2 id="goal-status-and-prerequisites" tabindex="-1">Objetivo, estado y requisitos <a class="header-anchor" href="#goal-status-and-prerequisites" aria-label="Permalink to &quot;Objetivo, estado y requisitos {#goal-status-and-prerequisites}&quot;">​</a></h2><p>Usa las notas históricas de RC2 para entender la corrección de lecturas simultáneas de Changes reproducida en RC1. El registro cubre AppImage, DEB y paquetes portátiles Linux compilados localmente mientras Actions estaba deshabilitado. No acredita descargas actuales ni un paquete Windows recién compilado. Elige artefactos de la <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">lista de versiones</a>, conserva sus checksums y prueba con un perfil aislado.</p><p>La recuperación Cloud y la colaboración siguen siendo experimentales. La búsqueda por apodo depende del backend <code>6a69c99</code> y de la migración <code>20261113000001_remote_invitation_recipients.sql</code>; el paquete de la aplicación no los despliega.</p><h2 id="correction-and-expected-behavior" tabindex="-1">Corrección y comportamiento esperado <a class="header-anchor" href="#correction-and-expected-behavior" aria-label="Permalink to &quot;Corrección y comportamiento esperado {#correction-and-expected-behavior}&quot;">​</a></h2><p>Las listas de Changes y conflictos y la selección del protocolo comparten observación del protocolo en lugar de reservar la admisión de mutaciones. Las lecturas de la barra y del panel pueden terminar mientras otra operación del diario de paquetes ocupa ese espacio. Se conservan las barreras de escritura, el aislamiento de cuentas y las decisiones explícitas de migración.</p><p>La comprobación de cuenta rechaza el cierre de sesión, las transiciones pendientes y las sesiones sustituidas. Leer la comparación local no restaura credenciales ni inicia una petición Cloud. Si falla, la interfaz muestra el motivo nativo y una recarga local; ese reintento no envía, descarga ni resuelve registros.</p><h2 id="check-the-candidate" tabindex="-1">Comprobar el candidato <a class="header-anchor" href="#check-the-candidate" aria-label="Permalink to &quot;Comprobar el candidato {#check-the-candidate}&quot;">​</a></h2><ol><li>Anota la versión mostrada <code>4.2.1-rc.2</code> y abre Plugins → Changes en un perfil aislado.</li><li>Abre o recarga la comparación desde la barra y el panel. Un fallo debe conservar su motivo en lugar de afirmar que todo está sincronizado.</li><li>Usa el reintento local y comprueba que recarga la comparación sin modificar colas pendientes ni aplicar registros remotos.</li><li>Registra por separado las transiciones de cuenta y sesión. Consulta el <a href="./4.2.1-rc.1.html">procedimiento RC1</a> al reproducir un perfil afectado.</li></ol><h2 id="recorded-validation-and-recovery" tabindex="-1">Validación registrada y recuperación <a class="header-anchor" href="#recorded-validation-and-recovery" aria-label="Permalink to &quot;Validación registrada y recuperación {#recorded-validation-and-recovery}&quot;">​</a></h2><p>El registro original describe una regresión determinista con 32 lectores, pruebas CloudAuth/sync/nativas/frontend y el inicio del AppImage optimizado con un perfil vacío aislado. También registra comprobaciones del contenido de instaladores y del archivo portátil. Aquel inicio no probó sincronización autenticada de producción ni reproducción multimedia.</p><p>El SHA-256 histórico del AppImage fue <code>35fc26e7bc5875c5a3fe99bf6a84baf77af8ca63d1c8b8e61825881187d6091f</code>. Identifica ese archivo registrado; usa el checksum adjunto al artefacto que realmente descargues.</p><p>Si la carga sigue fallando, conserva versión, error nativo e identificador de petición y consulta <a href="./../user/preferences/troubleshooting.html">Diagnósticos</a>. Conserva ediciones pendientes y conflictos. En RC2, Automations usaba una referencia local, faltaba trabajo de Variables y Overlays, y seguía sin identificarse al responsable del bloqueo SQLite histórico. Estas notas no afirman que se haya desplegado posteriormente la ruta de búsqueda de personas ausente en el backend antiguo.</p><p>El <a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.2.md" target="_blank" rel="noreferrer">registro original</a> se conserva como evidencia fechada. Vuelve al <a href="./">índice de versiones</a>.</p>',14)])])}const m=a(s,[["render",c]]);export{b as __pageData,m as default};
